function pageSearch(){const q=new URLSearchParams(document.body.dataset.route||'');for(const [k,v] of new URLSearchParams(location.search))q.set(k==='id'?'article':k,v);return '?'+q;}
function pageLink(value){
 const url=new URL(value,location.href);
 if(url.origin!==location.origin || !url.pathname.endsWith('/index.html'))return value;
 const q=url.searchParams;
 if(q.has('article'))return './article.html?id='+encodeURIComponent(q.get('article'))+url.hash;
 if(q.has('category')){
 const category=q.get('category').toUpperCase();
 const sub=q.get('subcategory');
 const query=new URLSearchParams();
 if(q.get('view')==='articles')query.set('view','articles');
 if(sub)query.set('subcategory',sub);
 return './'+category.toLowerCase()+'.html'+(query.size?'?'+query:'')+url.hash;
 }
 return value;
}
function updateLinks(){document.querySelectorAll('a[href]').forEach(a=>{const href=a.getAttribute('href');const next=pageLink(href);if(next!==href)a.setAttribute('href',next)});}
